    for j, v in enumerate(t["v"]):
        v.pop("all_", None)
        tg = v.pop("tag", None)
        if tg is not None and tg[1] != 0:
            LAW_TAGS.setdefault(t["id"], {})[j] = [tg[0], tg[1]]
        if "a" in v:
            for k in ("other_rev_gdp", "infl_shift", "unemp_shift"):
                v["a"].pop(k, None)
            if not v["a"]:
                v.pop("a")
